// sjalarm (owner Safe Journey order 3 Nov, Card 2): the destination alarm's
// REAL LIFE rule + PROOF replay.
//
//  * decideRing / SpeedSmoother unit tests (pure Dart);
//  * EVERY trace in test/testdata/dest_traces/ is replayed through the exact
//    code the phone runs (DestEngine: smoothing + decision + adaptive GPS
//    interval) — the alarm must ring BEFORE the stop, inside the trace's
//    expected lead window. Today all traces are SYNTHETIC (generated by
//    tools/train/make_synthetic_traces.py, each file says so); the owner's
//    real traces (trip recorder, owner-only) are added as real_*.json and run
//    here unchanged.
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import 'package:assisto/train/dest_alarm_decide.dart';
import 'package:assisto/train/dest_alarm_math.dart';
import 'package:assisto/train/trip_trace.dart';

const _lat = 23.7385, _lng = 90.3960; // Shahbag
(double, double) _north(double m) => (_lat + m / 111320.0, _lng);

List<(String, TripTrace)> _traces() {
  final dir = Directory('test/testdata/dest_traces');
  final out = <(String, TripTrace)>[];
  for (final f in dir.listSync().whereType<File>().where((f) => f.path.endsWith('.json'))) {
    final t = TripTrace.decode(f.readAsStringSync());
    // runs while tests are declared: a bad file fails loudly, not silently
    if (t == null) throw StateError('${f.path} is not an assisto-trip-trace/1 file');
    out.add((f.uri.pathSegments.last, t));
  }
  out.sort((a, b) => a.$1.compareTo(b.$1));
  return out;
}

void main() {
  group('decideRing (distance OR ~45 s at current speed, whichever first)', () {
    test('distance setting rings (never late: accuracy counts toward you)', () {
      expect(decideRing(distanceM: 9, accuracyM: 0, setM: 10), RingReason.distance);
      expect(decideRing(distanceM: 25, accuracyM: 15, setM: 10), RingReason.distance);
      expect(decideRing(distanceM: 40, accuracyM: 5, setM: 10), RingReason.none);
    });

    test('speed rule: 10 m/s rings ~450 m before a 10 m setting', () {
      expect(decideRing(distanceM: 500, accuracyM: 10, setM: 10, speedMps: 10), RingReason.none);
      expect(decideRing(distanceM: 455, accuracyM: 10, setM: 10, speedMps: 10), RingReason.eta);
      // a long-distance coach at 25 m/s rings before its 2 km setting
      expect(decideRing(distanceM: 1100, accuracyM: 10, setM: 2000, speedMps: 25),
          RingReason.distance);
      expect(decideRing(distanceM: 2200, accuracyM: 10, setM: 1000, speedMps: 25), RingReason.none);
      expect(decideRing(distanceM: 1100, accuracyM: 10, setM: 1000, speedMps: 25), RingReason.eta);
    });

    test('standing still (below 1.2 m/s) never rings by speed', () {
      expect(decideRing(distanceM: 30, accuracyM: 5, setM: 10, speedMps: 1.0), RingReason.none);
    });

    test('effective zone + low-power GPS only while far', () {
      expect(effectiveSetM(10, 10), 450);
      expect(effectiveSetM(2000, 10), 2000);
      expect(effectiveSetM(10, 0.5), 10);
      expect(lowPowerGpsOk(20000, 20, 2000, 0), isTrue);
      expect(lowPowerGpsOk(4000, 20, 10, 10), isFalse); // 30 m/s assumed: zone 1350 m
      expect(lowPowerGpsOk(6000, 3000, 10, 10), isFalse); // coarse fix: be careful
    });
  });

  group('SpeedSmoother (GPS jitter must not look like driving)', () {
    final t0 = DateTime.utc(2026, 11, 3, 8);

    test('jitter inside the accuracy circle at a standstill = 0 m/s', () {
      final s = SpeedSmoother();
      final jitter = [0.0, 9.0, -7.0, 12.0, -10.0, 4.0, 11.0, -6.0, 8.0, -12.0];
      for (var i = 0; i < 60; i++) {
        final p = _north(400 + jitter[i % jitter.length]);
        s.update(p.$1, p.$2, 25, t0.add(Duration(seconds: i)));
      }
      expect(s.mps, lessThan(kStillMps));
      final p = _north(400);
      expect(decideRing(distanceM: 400, accuracyM: 25, setM: 10, speedMps: s.mps), RingReason.none,
          reason: '${p.$1}');
    });

    test('positions only (no Doppler): a bus at 10 m/s reads ~10 m/s', () {
      final s = SpeedSmoother();
      for (var i = 0; i < 40; i++) {
        final p = _north(2000 - 10.0 * i);
        s.update(p.$1, p.$2, 10, t0.add(Duration(seconds: i)));
      }
      expect(s.mps, closeTo(10, 1.0));
    });

    test('one jumped fix cannot spike the speed', () {
      final s = SpeedSmoother();
      for (var i = 0; i < 10; i++) {
        s.update(_lat, _lng, 5, t0.add(Duration(seconds: i)), gpsSpeedMps: 0);
      }
      s.update(_lat, _lng, 5, t0.add(const Duration(seconds: 10)), gpsSpeedMps: 60);
      expect(s.mps, lessThan(kStillMps)); // capped by believable acceleration, then smoothed
    });

    test('Doppler speed from the phone is used directly (smoothed)', () {
      final s = SpeedSmoother();
      for (var i = 0; i < 30; i++) {
        s.update(_lat, _lng, 5, t0.add(Duration(seconds: i)), gpsSpeedMps: 15);
      }
      expect(s.mps, closeTo(15, 0.1));
    });
  });

  group('trip trace format', () {
    test('JSON round trip + GPX with timestamps, accuracy and speed', () {
      final t = TripTrace(mode: 'cityBus', setM: 10, points: [
        TracePoint(DateTime.utc(2026, 11, 3, 8), _lat, _lng, 8.5, speed: 3.2),
        TracePoint(DateTime.utc(2026, 11, 3, 8, 0, 1), _lat + 0.0001, _lng, 9, speed: null),
      ]).withStop(_lat, _lng, 'Shahbag <1>');
      final back = TripTrace.decode(t.encode())!;
      expect(back.points.length, 2);
      expect(back.points.first.speed, 3.2);
      expect(back.points.last.speed, isNull);
      expect(back.stopName, 'Shahbag <1>');
      expect(back.synthetic, isFalse);
      final gpx = t.toGpx();
      expect(gpx, contains('<time>2026-11-03T08:00:00.000Z</time>'));
      expect(gpx, contains('<acc>8.5</acc>'));
      expect(gpx, contains('Shahbag &lt;1&gt;'));
      expect(TripTrace.decode('{"format":"other"}'), isNull);
      expect(TripTrace.decode('not json'), isNull);
    });
  });

  group('CI replay: every trace rings BEFORE the stop', () {
    final traces = _traces();

    test('trace folder has the four journey kinds', () {
      final modes = {for (final (_, t) in traces) t.mode};
      expect(modes, containsAll(['cityBus', 'longBus', 'train', 'walking']));
      for (final (name, t) in traces) {
        expect(t.stopLat, isNotNull, reason: '$name: no stop');
        expect(t.points.length, greaterThan(50), reason: name);
        // honesty: synthetic files are named and marked so
        if (name.startsWith('synthetic_')) {
          expect(t.synthetic, isTrue, reason: name);
          expect(t.note, startsWith('SYNTHETIC'), reason: name);
        }
        if (name.startsWith('real_')) expect(t.synthetic, isFalse, reason: name);
      }
    });

    for (final (name, t) in traces) {
      test('$name rings before the stop (lead ${t.minLeadS}-${t.maxLeadS} s)', () {
        for (final batt in [80, 10]) {
          final r = replayTrace(t, batteryPct: batt);
          expect(r.arriveAt, isNotNull, reason: name);
          expect(r.ringAt, isNotNull, reason: '$name: never rang (battery $batt%)');
          final lead = r.leadS!;
          // ignore: avoid_print
          print('replay $name battery=$batt% lead=${lead}s reason=${r.reason.name} '
              'at=${r.ringDistanceM?.round()}m fixes=${r.fixesUsed}');
          expect(lead, greaterThanOrEqualTo(t.minLeadS), reason: '$name rang too late ($lead s)');
          expect(lead, lessThanOrEqualTo(t.maxLeadS), reason: '$name rang far too early ($lead s)');
        }
      });
    }

    test('the speed rule is what saves the fast city-bus traces (distance-only is late)', () {
      final city = [for (final (n, t) in traces) if (t.mode == 'cityBus' && n.startsWith('synthetic_')) t];
      expect(city, isNotEmpty);
      for (final t in city) {
        final r = replayTrace(t, etaS: 0);
        expect(r.leadS == null || r.leadS! < t.minLeadS, isTrue,
            reason: 'distance-only should not be enough at 10 m');
      }
    });
  });
}
